// Replaces the placeholder catalog images with realistic product photos generated by Gemini.
// Usage: npm run catalog:images [-- SKU ...]   (all products when no SKU is given)
import { writeFile } from "node:fs/promises";
import path from "node:path";
import { Modality } from "@google/genai";
import sharp from "sharp";
import { config } from "../config.js";
import { pool } from "../db/pool.js";
import { assetsDir } from "../paths.js";
import { gemini } from "../tryon/gemini.js";

interface Row {
  sku: string;
  name: string;
  description: string;
  imageUrl: string;
  attributes: Record<string, unknown>;
}

const skus = process.argv.slice(2);

try {
  const { rows } = await pool.query<Row>(
    `SELECT sku, name, description, image_url AS "imageUrl", attributes FROM products
     WHERE cardinality($1::text[]) = 0 OR sku = ANY($1) ORDER BY sku`,
    [skus],
  );
  for (const product of rows) {
    const res = await gemini().models.generateContent({
      model: config.GEMINI_IMAGE_MODEL,
      contents: `Professional e-commerce product photo of a single "${product.name}": ${product.description}
Details: ${JSON.stringify(product.attributes)}.
Show only the product, centered, fully in frame, on a plain light grey studio background with soft even lighting.
No people, mannequins, text, logos or props.`,
      config: { responseModalities: [Modality.IMAGE], imageConfig: { aspectRatio: "1:1" } },
    });
    const data = res.candidates?.[0]?.content?.parts?.find((p) => p.inlineData?.data)?.inlineData?.data;
    if (!data) {
      console.error(`${product.sku}: no image returned`);
      continue;
    }
    const file = path.join(assetsDir, product.imageUrl.slice("/assets/".length));
    await writeFile(file, await sharp(Buffer.from(data, "base64")).resize(1024, 1024).png().toBuffer());
    console.log(`${product.sku}: saved ${path.relative(process.cwd(), file)}`);
  }
} catch (err) {
  console.error((err as Error).message);
  process.exitCode = 1;
} finally {
  await pool.end();
}
